import React from 'react';
import { NavLink } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { 
  LayoutDashboard, 
  PawPrint, 
  Stethoscope, 
  Droplets, 
  Baby, 
  Wallet, 
  Package, 
  ClipboardList, 
  BarChart3, 
  Settings,
  ShieldCheck,
  Cpu,
  X
} from 'lucide-react';

const navItems = [
  { to: '/dashboard', label: 'Dashboard', icon: LayoutDashboard },
  { to: '/animals', label: 'Hayvanlar', icon: PawPrint },
  { to: '/health', label: 'Sağlık', icon: Stethoscope },
  { to: '/milk', label: 'Süt Üretimi', icon: Droplets },
  { to: '/reproduction', label: 'Üreme', icon: Baby },
  { to: '/finance', label: 'Finans', icon: Wallet },
  { to: '/inventory', label: 'Envanter', icon: Package },
  { to: '/tasks', label: 'Görevler', icon: ClipboardList },
  { to: '/smart-farm', label: 'Akıllı Çiftlik & Tesis', icon: Cpu },
  { to: '/reports', label: 'Raporlar', icon: BarChart3 },
  { to: '/settings', label: 'Ayarlar', icon: Settings },
];

export default function Sidebar({ open, onClose }) {
  const { user } = useAuth();

  const isAdmin = user && (user.role?.toLowerCase() === 'admin' || user.is_admin);

  // Admin bağlantısını Ayarlar'ın hemen önüne ekle
  const settingsItem = navItems.find(item => item.to === '/settings');
  const baseItems = navItems.filter(item => item.to !== '/settings');
  const visibleItems = isAdmin 
    ? [...baseItems, { to: '/admin', label: 'Admin Paneli', icon: ShieldCheck }, settingsItem]
    : navItems;

  return (
    <>
      {/* Mobil Karartma Arka Planı (Backdrop) */}
      {open && (
        <div 
          className="fixed inset-0 bg-black/40 backdrop-blur-xs z-40 lg:hidden transition-opacity duration-300" 
          onClick={onClose}
          aria-hidden="true"
        />
      )}

      {/* Ana Kenar Çubuğu (Sidebar) */}
      <aside 
        className={`
          fixed inset-y-0 left-0 z-50
          lg:static lg:translate-x-0
          flex flex-col text-white
          transform transition-all duration-300 ease-in-out select-none
          ${open ? 'translate-x-0 w-64 md:w-72' : '-translate-x-full w-64 md:w-72 lg:w-20'}
        `}
        style={{ 
          background: 'linear-gradient(180deg, #0d9488 0%, #0f766e 50%, #0d6b5e 100%)',
          boxShadow: open ? '4px 0 30px rgba(13, 148, 136, 0.25)' : 'none'
        }}
        aria-label="Ana Menü"
      >
        {/* Logo & Başlık Alanı */}
        <div 
          className={`flex items-center py-5 transition-all ${
            open ? 'justify-between px-4 sm:px-5' : 'justify-center px-2'
          }`} 
          style={{ borderBottom: '1px solid rgba(255, 255, 255, 0.1)' }}
        >
          <div className="flex items-center gap-3 min-w-0">
            <img 
              src="/mFk.png" 
              alt="mFk Farm Logo" 
              className="w-10 h-10 object-contain flex-shrink-0 mfk-logo bg-transparent border-0 outline-none shadow-none"
              style={{ backgroundColor: 'transparent' }} 
            />
            {open && (
              <div className="overflow-hidden whitespace-nowrap">
                <span className="font-bold text-lg block leading-tight tracking-tight text-white">mFk Farm</span>
                <span className="text-[10px] text-teal-200 uppercase tracking-[0.15em] font-semibold block">Management</span>
              </div>
            )}
          </div>

          {/* Mobilde Kapatma Butonu */}
          {open && (
            <button 
              onClick={onClose}
              className="lg:hidden p-1.5 rounded-lg text-white/80 hover:text-white hover:bg-white/10 active:scale-95 transition-all"
              aria-label="Menüyü Kapat"
            >
              <X className="w-5 h-5" />
            </button>
          )}
        </div>

        {/* Menü Linkleri Navigasyonu */}
        <nav className={`flex-1 py-4 overflow-y-auto space-y-1 scrollbar-thin ${open ? 'px-3' : 'px-2'}`}>
          {visibleItems.map(item => (
            <NavLink
              key={item.to}
              to={item.to}
              onClick={() => window.innerWidth < 1024 && onClose()}
              title={!open ? item.label : undefined}
              className={({ isActive }) =>
                `sidebar-link group relative flex items-center rounded-xl font-medium transition-all duration-200 ${
                  isActive 
                    ? 'active bg-white text-teal-800 shadow-md font-semibold' 
                    : 'text-white/80 hover:text-white hover:bg-white/10'
                } ${
                  open 
                    ? 'gap-3 px-3.5 py-2.5 text-sm' 
                    : 'justify-center py-2.5 px-0 lg:justify-center'
                }`
              }
            >
              <item.icon className="w-5 h-5 flex-shrink-0 transition-transform duration-200 group-hover:scale-105" />
              
              {open && (
                <>
                  <span className="truncate flex-1">{item.label}</span>
                  {item.badge && (
                    <span className="text-[10px] font-black px-1.5 py-0.5 rounded-full bg-amber-400 text-teal-950 shadow-xs">
                      {item.badge}
                    </span>
                  )}
                </>
              )}

              {/* Mobilde sidebar açıkken etiket göster */}
              {!open && (
                <span className="lg:hidden truncate">{item.label}</span>
              )}

              {/* Masaüstünde daraltılmış modda hover tooltip */}
              {!open && (
                <div className="hidden lg:group-hover:block absolute left-full ml-3 px-2.5 py-1.5 bg-gray-900 text-white text-xs font-medium rounded-lg shadow-xl whitespace-nowrap z-50 pointer-events-none animate-fade-in">
                  {item.label}
                </div>
              )}
            </NavLink>
          ))}
        </nav>
      </aside>
    </>
  );
}
