import React, { createContext, useContext, useState, useEffect } from 'react';
import { authService } from '../services/api';

const AuthContext = createContext(null);

const normalizeUser = (u) => {
  if (!u) return null;
  const adminFlag = Boolean(
    u.role?.toLowerCase() === 'admin' || 
    u.isAdmin === true || 
    u.is_admin === true
  );
  return {
    ...u,
    isAdmin: adminFlag,
    is_admin: adminFlag
  };
};

export function AuthProvider({ children }) {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const handleLogout = () => {
      setUser(null);
    };
    window.addEventListener('auth:logout', handleLogout);
    return () => window.removeEventListener('auth:logout', handleLogout);
  }, []);

  useEffect(() => {
    let token = localStorage.getItem('token');
    let stored = localStorage.getItem('user');
    let isFromLocalStorage = true;

    // localStorage'da yoksa sessionStorage'dan dene
    if (!token && typeof sessionStorage !== 'undefined') {
      token = sessionStorage.getItem('token');
      stored = sessionStorage.getItem('user');
      isFromLocalStorage = false;
    }

    if (token && stored) {
      try {
        const userData = normalizeUser(JSON.parse(stored));
        setUser(userData);

        // Profil verisini ve güncel rolünü (admin vb.) arka planda doğrula / güncelle
        authService.getMe()
          .then(res => {
            if (res.data?.user) {
              const freshUser = normalizeUser(res.data.user);
              setUser(freshUser);
              if (isFromLocalStorage) {
                localStorage.setItem('user', JSON.stringify(freshUser));
              } else if (typeof sessionStorage !== 'undefined') {
                sessionStorage.setItem('user', JSON.stringify(freshUser));
              }
            }
          })
          .catch(err => {
            if (err.response?.status === 401) {
              localStorage.removeItem('token');
              localStorage.removeItem('user');
              if (typeof sessionStorage !== 'undefined') {
                sessionStorage.removeItem('token');
                sessionStorage.removeItem('user');
              }
              setUser(null);
            }
          });
      } catch (e) {
        console.error('Failed to parse user from storage:', e);
        localStorage.removeItem('token');
        localStorage.removeItem('user');
        if (typeof sessionStorage !== 'undefined') {
          sessionStorage.removeItem('token');
          sessionStorage.removeItem('user');
        }
        setUser(null);
      }
    }
    setLoading(false);
  }, []);

  const login = async (email, password, rememberMe = false) => {
    try {
      const res = await authService.login(email, password);
      const { token, user: u } = res.data;
      const normalized = normalizeUser(u);
      if (rememberMe) {
        localStorage.setItem('token', token);
        localStorage.setItem('user', JSON.stringify(normalized));
        if (typeof sessionStorage !== 'undefined') {
          sessionStorage.removeItem('token');
          sessionStorage.removeItem('user');
        }
      } else {
        if (typeof sessionStorage !== 'undefined') {
          sessionStorage.setItem('token', token);
          sessionStorage.setItem('user', JSON.stringify(normalized));
        }
        localStorage.removeItem('token');
        localStorage.removeItem('user');
      }
      setUser(normalized);
      return normalized;
    } catch (error) {
      console.error('AuthContext login error:', error);
      throw error;
    }
  };

  const loginDemo = async () => {
    try {
      const res = await authService.demo();
      const { token, user: u } = res.data;
      const normalized = normalizeUser(u);
      localStorage.setItem('token', token);
      localStorage.setItem('user', JSON.stringify(normalized));
      if (typeof sessionStorage !== 'undefined') {
        sessionStorage.removeItem('token');
        sessionStorage.removeItem('user');
      }
      setUser(normalized);
      return normalized;
    } catch (error) {
      console.error('AuthContext loginDemo error:', error);
      throw error;
    }
  };

  const register = async (data) => {
    try {
      const res = await authService.register(data);
      if (res.data?.token && res.data?.user) {
        const normalized = normalizeUser(res.data.user);
        localStorage.setItem('token', res.data.token);
        localStorage.setItem('user', JSON.stringify(normalized));
        if (typeof sessionStorage !== 'undefined') {
          sessionStorage.removeItem('token');
          sessionStorage.removeItem('user');
        }
        setUser(normalized);
      }
      return res.data;
    } catch (error) {
      console.error('AuthContext register error:', error);
      throw error;
    }
  };

  const refreshToken = async () => {
    let token = localStorage.getItem('token');
    let isFromLocalStorage = true;
    if (!token && typeof sessionStorage !== 'undefined') {
      token = sessionStorage.getItem('token');
      isFromLocalStorage = false;
    }
    if (!token) return null;

    try {
      const res = await authService.refreshToken(token);
      const { token: newToken, user: u } = res.data;
      const normalized = normalizeUser(u);
      if (isFromLocalStorage) {
        localStorage.setItem('token', newToken);
        localStorage.setItem('user', JSON.stringify(normalized));
      } else if (typeof sessionStorage !== 'undefined') {
        sessionStorage.setItem('token', newToken);
        sessionStorage.setItem('user', JSON.stringify(normalized));
      }
      setUser(normalized);
      return { token: newToken, user: normalized };
    } catch (err) {
      console.error('AuthContext refreshToken error:', err);
      logout();
      throw err;
    }
  };

  const logout = () => {
    authService.logout();
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    if (typeof sessionStorage !== 'undefined') {
      sessionStorage.removeItem('token');
      sessionStorage.removeItem('user');
    }
    setUser(null);
  };

  const updateUser = (updatedFields) => {
    setUser(prev => {
      if (!prev) return prev;
      const merged = { ...prev, ...updatedFields };
      const next = normalizeUser(merged);
      if (localStorage.getItem('user')) {
        localStorage.setItem('user', JSON.stringify(next));
      }
      if (typeof sessionStorage !== 'undefined' && sessionStorage.getItem('user')) {
        sessionStorage.setItem('user', JSON.stringify(next));
      }
      return next;
    });
  };

  const isAdmin = Boolean(
    user && (user.role?.toLowerCase() === 'admin' || user.isAdmin === true || user.is_admin === true)
  );

  return (
    <AuthContext.Provider value={{
      user,
      login,
      loginDemo,
      register,
      refreshToken,
      logout,
      updateUser,
      loading,
      isAuthenticated: !!user,
      isAdmin
    }}>
      {children}
    </AuthContext.Provider>
  );
}

export const useAuth = () => {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error('useAuth must be inside AuthProvider');
  return ctx;
};